    'Przenieś całą zapisaną rozmowę, listę kontrolną, załączniki i pliki. Sesje dostawcy i dane uwierzytelniające pozostają tutaj. Wątek docelowy korzysta z domyślnej wiązki przewodów tego komputera i nie ma większego dostępu niż ten wątek. Nic nie działa, dopóki nie wyślesz tam następnej wiadomości. Po otwarciu możesz zmienić jego model. Ten wątek pozostaje tutaj w trybie tylko do odczytu i można go odzyskać.',
  'Copy files and local Git history. The source project and chats stay here. A new folder is created on the destination. Worktrees use its configured worktree directory.':
    'Skopiuj pliki i lokalną historię Git. Projekt źródłowy i czaty pozostają tutaj. W miejscu docelowym zostanie utworzony nowy folder. Worktrees korzystają ze skonfigurowanego katalogu worktree.',
