  'Set up CuaDriver on this runtime host. CuaDriver owns OS permissions; Dovo connects agents through MCP.':
    'Skonfiguruj CuaDriver na tym hoście wykonawczym. CuaDriver posiada uprawnienia systemu operacyjnego; Dovo łączy agentów poprzez MCP.',
  'Host executable names or paths, without shell quoting. Agent overrides take precedence. New terminals use these shell settings.':
    'Nazwy lub ścieżki plików wykonywalnych hosta, bez cytowania powłoki. Zastąpienia agenta mają pierwszeństwo. Nowe terminale korzystają z tych ustawień powłoki.',
