  'Enable agent computer use on this computer':
    'Włącz korzystanie z komputera agenta na tym komputerze',
  'Grants writable agents access to this computer’s desktop. Read-only agents are excluded. The user and agents share the desktop and app state.':
    'Przyznaje agentom z możliwością zapisu dostęp do pulpitu tego komputera. Agenci tylko do odczytu są wykluczeni. Użytkownik i agenci udostępniają stan pulpitu i aplikacji.',
  'Leave Cua Driver empty to detect it on this computer’s PATH or in its standard installation folder. Changes apply to new agent turns.':
    'Pozostaw sterownik Cua pusty, aby wykryć go w ścieżce PATH tego komputera lub w jego standardowym folderze instalacyjnym. Zmiany dotyczą nowych tur agentów.',
  '1. Install on this computer': '1. Zainstaluj na tym komputerze',
  'Run the official installer on the runtime host, then refresh status. It downloads and installs CuaDriver; no Cua account is required.':
    'Uruchom oficjalny instalator na hoście wykonawczym, a następnie odśwież status. Pobiera i instaluje CuaDriver; nie jest wymagane konto Cua.',
  'Minimal Linux systems need libxi6 and at-spi2-core. GNOME needs Cua’s bundled WinRects helper; see the installation guide.':
    'Minimalne systemy Linux wymagają bibliotek libxi6 i at-spi2-core. GNOME potrzebuje dołączonego pomocnika WinRects Cua; zobacz instrukcję instalacji.',
  'Install and set up Cua Driver': 'Zainstaluj i skonfiguruj sterownik Cua',
  'Detect / check Cua Driver': 'Wykryj/sprawdź sterownik Cua',
  '2. Permissions & desktop access': '2. Uprawnienia i dostęp do pulpitu',
  '3. Agent MCP, skills & hooks': '3. Agent MCP, umiejętności i haczyki',
  '4. Computer History (optional preview)': '4. Historia komputera (opcjonalny podgląd)',
  'Grant macOS Accessibility and Screen Recording to CuaDriver and accept its relaunch. Test desktop access lists apps without changing them. Daemon controls affect active computer-use sessions.':
    'Przyznaj CuaDriver dostępność i nagrywanie ekranu macOS i zaakceptuj jego ponowne uruchomienie. Przetestuj listę aplikacji dostępnych na pulpicie bez ich zmiany. Kontrole demonów wpływają na aktywne sesje korzystania z komputera.',
  'Save the computer-use switch for automatic dovo_cua MCP on new writable turns. No manual MCP registration is needed. Install the optional official skill pack; installation links detected agents on this computer.':
    'Zapisz przełącznik korzystania z komputera dla automatycznego dovo_cua MCP w przypadku nowych zapisywalnych obrotów. Nie jest wymagana ręczna rejestracja MCP. Zainstaluj opcjonalny oficjalny pakiet umiejętności; instalacja łączy wykrytych agentów na tym komputerze.',
  'Opt-in, encrypted, metadata-only history. Enable may restart the daemon. Disable keeps recorded data; pause temporarily stops recording. Unsupported builds report an error. Data stays on the runtime host; View recent history retrieves up to 20 events here.':
    'Rejestracja, szyfrowana, historia zawierająca wyłącznie metadane. Włącz może zrestartować demona. Wyłącz zachowuje zapisane dane; pauza tymczasowo zatrzymuje nagrywanie. Nieobsługiwane kompilacje zgłaszają błąd. Dane pozostają na hoście wykonawczym; Zobacz najnowszą historię, która zawiera do 20 zdarzeń.',
  'Delete recorded Computer History?': 'Usunąć zapisaną historię komputera?',
  'Delete all recorded history and its encryption key on this computer. This cannot be undone.':
    'Usuń całą zapisaną historię i jej klucz szyfrowania na tym komputerze. Tego nie można cofnąć.',
