  'Computer defaults apply when scoped Task lifecycle settings inherit. Scoped restart and archiving rules take precedence.':
    'Ustawienia domyślne komputera mają zastosowanie w przypadku dziedziczenia ustawień cyklu życia zadania w określonym zakresie. Pierwszeństwo mają reguły dotyczące ponownego uruchamiania i archiwizowania o określonym zakresie.',
