  'Prompt suggestions': 'Szybkie sugestie',
  'Tab completion': 'Uzupełnianie zakładek',
  'Suggest a next prompt after a Claude or Codex turn. Tap the suggestion to insert it without sending. On desktop, press Tab to insert it or Escape to dismiss it. Each suggestion makes an extra model request and uses plan usage.':
    'Zaproponuj kolejne polecenie po odpowiedzi Claude lub Codex. Dotknij propozycji, aby ją wstawić bez wysyłania. Na komputerze naciśnij Tab, aby ją wstawić, lub Escape, aby ją odrzucić. Każda propozycja wymaga dodatkowego zapytania do modelu i zużywa limit planu.',
  'Scheduled worker capacity': 'Zaplanowana wydajność pracowników',
  'Scheduled jobs wait at this threshold. One slot stays available for conversation work. Direct messages and needed children can exceed it. Running work is kept.':
    'Zaplanowane zadania oczekują na tym progu. Jedno miejsce pozostaje dostępne do pracy konwersacyjnej. Bezpośrednie wiadomości i potrzebne dzieci mogą to przekroczyć. Bieżąca praca zostaje zachowana.',
  'Continue interrupted turns after runtime restart':
    'Kontynuuj przerwane tury po ponownym uruchomieniu',
  'Interrupted turns can resume automatically. Queued messages stay paused until you resume them. Stopped tasks and automations still require Retry.':
    'Przerwane zakręty mogą zostać wznowione automatycznie. Wiadomości w kolejce pozostają wstrzymane do czasu ich wznowienia. Zatrzymane zadania i automatyzacje nadal wymagają ponownej próby.',
  'Auto-archive inactive tasks': 'Automatycznie archiwizuj nieaktywne zadania',
