  'After 7 days': 'Po 7 dniach',
  'After 14 days': 'Po 14 dniach',
  'After 30 days': 'Po 30 dniach',
  'Computer fallback when no scoped archiving rule is set. Scoped On archives after time in Settled; scoped Off disables automatic archiving. Running, waiting, pinned tasks and open terminals are protected.':
    'Rezerwa komputera, jeśli nie ustawiono żadnej reguły archiwizacji w zakresie. Scoped On archiwa po czasie w Settled; zakres Wyłączony wyłącza automatyczną archiwizację. Uruchomione, oczekujące, przypięte zadania i otwarte terminale są chronione.',
  'Keep this computer awake while tasks run':
    'Nie wyłączaj tego komputera podczas wykonywania zadań',
  'macOS only. Prevents idle sleep while a task is working, so it keeps going while you follow it here.':
    'Tylko dla systemu macOS. Zapobiega bezczynności podczas wykonywania zadania, więc działa dalej, gdy wykonujesz je tutaj.',
  'Model modes (experimental)': 'Tryby modelu (eksperymentalne)',
  'Tune & Maestro modes (experimental)': 'Tryby Tune i Maestro (eksperymentalne)',
