    'Tune wybiera model w ramach domyślnego agenta. Maestro wspólnie wybiera agenta i model. Obaj wybierają rozumowanie raz przed pierwszą turą. Dziedzicz zachowuje ustawienia domyślne projektu.',
  'Project mode (experimental)': 'Tryb projektu (eksperymentalny)',
