  'Relay fallback': 'Awaryjny przekaźnik',
  'The computer must allow relay in its pairing QR. For a Direct-only pairing, generate a new Dovo-enabled QR on the computer and pair again.':
    'Komputer musi umożliwiać przekaźnikowi parowanie QR. W przypadku parowania wyłącznie bezpośredniego wygeneruj na komputerze nowy kod QR obsługujący Dovo i sparuj ponownie.',
  'Scan pairing QR code': 'Zeskanuj kod QR parowania',
  'Point your camera at the QR code shown by Dovo Studio or the server’s pair command.':
    'Skieruj aparat na kod QR pokazany przez Dovo Studio lub polecenie parowania serwera.',
  'Allow camera access to scan a pairing code. You can also enter the address and code manually.':
    'Zezwól na dostęp aparatu do zeskanowania kodu parowania. Możesz także wpisać adres i kod ręcznie.',
  'Allow camera': 'Zezwól na kamerę',
  'Open Settings': 'Otwórz Ustawienia',
  'Try another code': 'Wypróbuj inny kod',
  'Enter address and code manually': 'Wprowadź adres i kod ręcznie',
  'Enter the new address and a fresh pairing code from the same computer. Your saved connection stays unchanged until pairing succeeds.':
    'Wprowadź nowy adres i nowy kod parowania z tego samego komputera. Twoje zapisane połączenie pozostanie niezmienione do momentu pomyślnego parowania.',
  'On your computer, open Dovo and choose {value0} in Settings → Devices & runtime.':
    'Na komputerze otwórz Dovo i wybierz {value0} w Ustawienia → Urządzenia i środowisko wykonawcze.',
  'Connect your phone': 'Podłącz telefon',
  'Scan the QR code in this app to connect over the internet. No VPN or local IP needed. You can also pair using a LAN / VPN address.':
    'Zeskanuj kod QR w tej aplikacji, aby połączyć się przez internet. VPN ani lokalny adres IP nie są potrzebne. Możesz też sparować urządzenia, używając adresu LAN / VPN.',
  'Internet connection': 'Połączenie internetowe',
  'WebRTC + STUN · end-to-end encrypted. No VPN or computer address needed. Keep Dovo open on the computer.':
    'WebRTC + STUN · szyfrowane od początku do końca. Nie jest wymagana żadna sieć VPN ani adres komputera. Pozostaw Dovo otwarte na komputerze.',
  'Use a LAN / VPN address instead': 'Zamiast tego użyj adresu LAN/VPN',
  'Computer address': 'Adres komputera',
  'Wi-Fi, Tailscale and NetBird addresses all work. Include the port.':
    'Wszystkie adresy Wi-Fi, Tailscale i NetBird działają. Uwzględnij port.',
