  'View tasks on this device': 'Wyświetl zadania na tym urządzeniu',
  'This computer connection changed. Choose where to create this work again.':
    'To połączenie komputera uległo zmianie. Wybierz, gdzie ponownie utworzyć tę pracę.',
  'Choose another computer': 'Wybierz inny komputer',
  'Choose where this work should run.': 'Wybierz, gdzie ta praca ma być uruchamiana.',
  'Shows connection details': 'Pokazuje szczegóły połączenia',
  'Reconnects. Touch and hold for details':
    'Łączy się ponownie. Dotknij i przytrzymaj, aby wyświetlić szczegóły',
  'This phone is no longer paired with a computer below. It was removed on that computer, or the runtime was reset. Pair it again from Devices in Settings.':
    'Ten telefon nie jest już sparowany z komputerem poniżej. Został usunięty z tego komputera lub środowisko wykonawcze zostało zresetowane. Sparuj go ponownie, korzystając z opcji Urządzenia w Ustawieniach.',
  'Connected using HTTP updates. Live streaming is reconnecting or unavailable. Reconnect to retry it.':
    'Połączono za pomocą aktualizacji HTTP. Transmisja na żywo ponownie się łączy lub jest niedostępna. Połącz się ponownie, aby spróbować jeszcze raz.',
  'Saved work stays available. Reconnect a computer to send messages or run commands there.':
    'Zapisane prace pozostają dostępne. Podłącz ponownie komputer, aby wysyłać na nim wiadomości lub uruchamiać polecenia.',
  '{value0} · {value1} saved actions': '{value0} · {value1} zapisane akcje',
  'Thread: {value0}': 'Temat: {value0}',
  'Computer access changed. This action may already have run.':
    'Zmieniono dostęp do komputera. Ta akcja mogła już zostać uruchomiona.',
  'Retry action': 'Ponów działanie',
