  'Dovo Connect: {value0}': 'Dovo Connect: {value0}',
  'Pair again': 'Sparuj ponownie',
  'Connection stages': 'Etapy połączenia',
  'Start your computer': 'Uruchom komputer',
  'Open Dovo on your computer and keep it awake. In Settings → Devices & runtime, sign in and enable Dovo Connect. Sign in to the same account on your phone and choose Connect. No pairing code, VPN or local IP is needed for internet access.':
    'Otwórz Dovo na swoim komputerze i nie wyłączaj go. W Ustawieniach → Urządzenia i czas działania zaloguj się i włącz Dovo Connect. Zaloguj się na to samo konto w telefonie i wybierz Połącz. Aby uzyskać dostęp do Internetu, nie jest potrzebny żaden kod parujący, VPN ani lokalny adres IP.',
  'Direct internet connection': 'Bezpośrednie połączenie internetowe',
  'WebRTC + STUN connects your phone directly to the computer. Your content is end-to-end encrypted. Enabling Dovo Connect permits an encrypted relay fallback if a network blocks direct connections. The relay forwards encrypted traffic; it cannot read your content.':
    'WebRTC + STUN łączy telefon bezpośrednio z komputerem. Twoje treści są szyfrowane od początku do końca. Włączenie Dovo Connect umożliwia zastępcze szyfrowanie przekaźnika, jeśli sieć blokuje połączenia bezpośrednie. Przekaźnik przekazuje zaszyfrowany ruch; nie może odczytać Twojej zawartości.',
  'LAN / VPN connections': 'Połączenia LAN/VPN',
  'Pair LAN / VPN separately to prefer that connection when available. Copy the full Wi-Fi, Tailscale, NetBird, or HTTPS address shown on your computer, including its port. localhost and 0.0.0.0 are not addresses your phone can connect to.':
    'Sparuj LAN / VPN oddzielnie, aby preferować to połączenie, jeśli jest dostępne. Skopiuj pełny adres Wi-Fi, Tailscale, NetBird lub HTTPS wyświetlony na komputerze, łącznie z jego portem. localhost i 0.0.0.0 nie są adresami, z którymi Twój telefon może się połączyć.',
  'Check your network': 'Sprawdź swoją sieć',
  'Use the same Wi-Fi or connect both devices to your VPN. For Wi-Fi connections, allow Dovo access to your Local Network in iPhone Settings.':
    "Użyj tej samej sieci Wi-Fi lub podłącz oba urządzenia do sieci VPN. W przypadku połączeń Wi-Fi zezwól Dovo na dostęp do sieci lokalnej w Ustawieniach iPhone'a.",
  'Pairing codes expire after two minutes. CLI codes approve automatically; a code from the desktop may need approval there.':
    'Kody parujące wygasają po dwóch minutach. Kody CLI zatwierdzają się automatycznie; kod z pulpitu może wymagać tam zatwierdzenia.',
  'Your pairing is saved. Try Reconnect before generating another code. If the address changed, choose Update connection address in this computer’s settings.':
    'Twoje parowanie zostało zapisane. Spróbuj ponownie połączyć się przed wygenerowaniem kolejnego kodu. Jeżeli adres się zmienił, wybierz opcję Aktualizuj adres połączenia w ustawieniach tego komputera.',
