  'Memory limit (MB)': 'Limit pamięci (MB)',
  "Runs each new thread's agent, its commands and its terminals in a local Docker or Podman container. Only the checkout and the selected harness login are mounted. Running threads keep their setting.":
    'Uruchamia agenta każdej nowej rozmowy, jego polecenia i terminale w lokalnym kontenerze Docker lub Podman. Montowane są tylko kopia robocza i dane logowania wybranego agenta. Trwające rozmowy zachowują swoje ustawienie.',
  'Without network access the harness cannot reach its model API unless that API runs inside the sandbox. Package installs and web requests also fail.':
    'Bez dostępu do sieci agent nie połączy się z API swojego modelu, chyba że to API działa w piaskownicy. Instalacje pakietów i żądania sieciowe również się nie powiodą.',
  preparing: 'przygotowywanie',
  stopped: 'zatrzymana',
  'A thread can change it before its first message.':
    'Rozmowa może to zmienić przed swoją pierwszą wiadomością.',
  'Full network access. The agent can reach any address the host can.':
    'Pełny dostęp do sieci. Agent może połączyć się z każdym adresem, z którym może połączyć się host.',
  'Leave empty for no limit.': 'Pozostaw puste, aby nie ustawiać limitu.',
  'Leave empty for the default of {value0} MB.':
    'Pozostaw puste, aby użyć domyślnej wartości {value0} MB.',
  'This thread runs in a Mise container sandbox.':
    'Ta rozmowa działa w kontenerowej piaskownicy Mise.',
  'The agent runs on this computer with your user account.':
    'Agent działa na tym komputerze z Twoim kontem użytkownika.',
  'The agent, its commands and its terminals run in a container. Only this checkout and the harness login are mounted.':
    'Agent, jego polecenia i terminale działają w kontenerze. Montowane są tylko ta kopia robocza i dane logowania agenta.',
  'Holds new work that runs without your message once its estimated cost reaches the limit. This covers Bot follow-ups, Bot routine steps, scheduled messages and child agents. Each thread or Bot counts with its child agents. A routine without a Bot starts a new count on each run. Set its own limits in Monitoring and limits. Your next message or Continue resets the count. Turns without a price also hold work. A running turn always finishes.':
    'Wstrzymuje nową pracę uruchamianą bez Twojej wiadomości, gdy jej szacowany koszt osiągnie limit. Dotyczy to dalszych kroków Botów, kroków rutyn Bota, zaplanowanych wiadomości i agentów podrzędnych. Każdy wątek lub Bot liczy się razem ze swoimi agentami podrzędnymi. Rutyna bez Bota zaczyna nowy licznik przy każdym uruchomieniu. Ustaw jej własne limity w sekcji Monitorowanie i limity. Twoja następna wiadomość lub Kontynuuj zeruje licznik. Tury bez ceny również wstrzymują pracę. Trwająca tura zawsze się kończy.',
  'During your request: "{value0}"': 'Podczas twojej prośby: "{value0}"',
  'Git hooks do not run for commits in a sandboxed thread. The agent can change files that hooks run.':
    'Hooki Git nie są uruchamiane przy commitach w wątku z piaskownicą. Agent może zmieniać pliki, które uruchamiają hooki.',
